<?php
require __DIR__.'/config.php';$user=require_login();$method=$_SERVER['REQUEST_METHOD']??'';$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT)?:0;
if($method==='GET'){
 if($user['rol']==='ADMIN'){$sql='SELECT p.*,u.nombre AS cliente FROM pedidos p JOIN clientes c ON c.id=p.cliente_id JOIN usuarios u ON u.id=c.usuario_id';$q=$id?db()->prepare($sql.' WHERE p.id=? ORDER BY p.fecha DESC'):db()->query($sql.' ORDER BY p.fecha DESC');if($id)$q->execute([$id]);$rows=$id?($q->fetchAll()):$q->fetchAll();}
 else{$q=db()->prepare('SELECT p.* FROM pedidos p JOIN clientes c ON c.id=p.cliente_id WHERE c.usuario_id=?'.($id?' AND p.id=?':'').' ORDER BY p.fecha DESC');$args=[$user['id']];if($id)$args[]=$id;$q->execute($args);$rows=$q->fetchAll();}
 if($id&&!$rows)json_response(false,null,'Pedido no encontrado.',404);
 if($id){$q=db()->prepare('SELECT d.*,pr.nombre AS producto FROM detalle_pedido d JOIN productos pr ON pr.id=d.producto_id WHERE d.pedido_id=?');$q->execute([$id]);$rows[0]['detalle']=$q->fetchAll();}
 json_response(true,$id?$rows[0]:$rows,'Pedidos consultados.');
}
if($method==='POST'){
 require_csrf();
 if($user['rol']!=='CLIENTE')json_response(false,null,'Solo los clientes pueden crear pedidos.',403);$data=body();$address=trim((string)($data['direccion']??''));if($address===''||mb_strlen($address)>255)json_response(false,null,'Ingresa una dirección de entrega válida.',400);$items=$data['items']??null;if(!is_array($items)||!count($items)||count($items)>100)json_response(false,null,'Agrega productos válidos al pedido.',400);
 $pdo=db();try{$pdo->beginTransaction();$q=$pdo->prepare('SELECT id FROM clientes WHERE usuario_id=?');$q->execute([$user['id']]);$cliente=$q->fetchColumn();if(!$cliente)json_response(false,null,'No se encontró el perfil del cliente.',404);$insert=$pdo->prepare("INSERT INTO pedidos(cliente_id,total,estado) VALUES(?,0,'PENDIENTE')");$insert->execute([$cliente]);$orderId=(int)$pdo->lastInsertId();$total=0.0;
  foreach($items as $item){$pid=filter_var($item['producto_id']??null,FILTER_VALIDATE_INT);$qty=filter_var($item['cantidad']??null,FILTER_VALIDATE_INT);if(!$pid||!$qty||$qty<1||$qty>10000)throw new DomainException('Los productos o cantidades del pedido no son válidos.');$q=$pdo->prepare("SELECT id,precio,stock FROM productos WHERE id=? AND estado='ACTIVO' FOR UPDATE");$q->execute([$pid]);$product=$q->fetch();if(!$product)throw new DomainException('Uno de los productos ya no está disponible.');if($product['stock']<$qty)throw new DomainException('Stock insuficiente para uno de los productos.');$unitCents=(int)round((float)$product['precio']*100);$subCents=$unitCents*$qty;$total+=(float)$subCents;$unit=number_format($unitCents/100,2,'.','');$sub=number_format($subCents/100,2,'.','');$pdo->prepare('INSERT INTO detalle_pedido(pedido_id,producto_id,cantidad,precio_unitario,subtotal) VALUES(?,?,?,?,?)')->execute([$orderId,$pid,$qty,$unit,$sub]);$pdo->prepare('UPDATE productos SET stock=stock-? WHERE id=?')->execute([$qty,$pid]);}
  $totalAmount=number_format($total/100,2,'.','');$pdo->prepare('UPDATE pedidos SET total=? WHERE id=?')->execute([$totalAmount,$orderId]);$pdo->prepare('INSERT INTO entregas(pedido_id,direccion) VALUES(?,?)')->execute([$orderId,$address]);$pdo->commit();json_response(true,['id'=>$orderId,'total'=>$totalAmount],'Pedido creado correctamente.',201);
 }catch(DomainException $e){if($pdo->inTransaction())$pdo->rollBack();json_response(false,null,$e->getMessage(),400);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
}
if($method==='PUT'){
  require_admin();require_csrf();$data=body();$id=$id?:((int)($data['id']??0));$state=$data['estado']??'';$states=['PENDIENTE','CONFIRMADO','EN_PREPARACION','ENVIADO','ENTREGADO','CANCELADO'];if(!$id||!in_array($state,$states,true))json_response(false,null,'Indica un pedido y un estado válido.',400);$pdo=db();$pdo->beginTransaction();$q=$pdo->prepare('SELECT estado FROM pedidos WHERE id=? FOR UPDATE');$q->execute([$id]);$previous=$q->fetchColumn();if($previous===false){$pdo->rollBack();json_response(false,null,'Pedido no encontrado.',404);}if($previous===$state){$pdo->rollBack();json_response(true,null,'El pedido ya tenía ese estado.');}if($state==='CANCELADO'&&in_array($previous,['ENVIADO','ENTREGADO'],true)){$pdo->rollBack();json_response(false,null,'No es posible cancelar un pedido enviado o entregado.',409);}if($state==='CANCELADO'&&$previous!=='CANCELADO'){$q=$pdo->prepare('SELECT producto_id,cantidad FROM detalle_pedido WHERE pedido_id=?');$q->execute([$id]);$restore=$pdo->prepare('UPDATE productos SET stock=stock+? WHERE id=?');foreach($q->fetchAll() as $item)$restore->execute([$item['cantidad'],$item['producto_id']]);}$q=$pdo->prepare('UPDATE pedidos SET estado=? WHERE id=?');$q->execute([$state,$id]);$pdo->commit();json_response(true,null,'Estado del pedido actualizado.');
}
require_method(['GET','POST','PUT']);
